// Maintained semantic guidance. Command inventory, flags, types and defaults come from the registry.
const example = (title, input = {}, common = {}) => ({ title, input, common });
const session = { session: '$SESSION_ID' };
const app = { vmUrl: '$VM_URL' };
const doc = (summary, use, result, notes, examples, related) => ({ summary, use, result, notes, examples, related });
export const groups = {
  setup: 'Discover commands and prepare a project',
  execution: 'Run tests and scripts in CI',
  catalog: 'Discover project tests without connecting to an app',
  app: 'Inspect and interact with a running app',
  native: 'Inspect native UI and prepare the XCTest Runner',
  scenario: 'Prepare a named app baseline',
  mock: 'Select HTTP response scenarios and inspect calls',
  artifacts: 'Investigate saved evidence without an app',
  flow: 'Inspect flows and compare runtime with Figma',
  generation: 'Generate test drafts from source or snapshots',
  tdd: 'Iterate on a focused test',
  session: 'Manage a reusable local connection',
};
export function commandGroup(path) {
  if (['schema', 'init', 'doctor', 'devices.list'].includes(path)) return 'setup';
  if (['run', 'script', 'record'].includes(path)) return 'execution';
  if (path === 'catalog') return 'catalog';
  if (path === 'generate-test') return 'generation';
  return path.split('.')[0];
}
